using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

// Builds visitor materials, prefabs and a preview scene from Visitors.fbx
// (generated by Tools/Blender/build_visitors.py). Safe to re-run; it overwrites its own outputs.
public static class VisitorModelBuilder
{
    const string ModelPath = "Assets/Models/Characters/Visitors.fbx";
    const string MaterialDir = "Assets/Models/Characters/Materials";
    const string PrefabDir = "Assets/Prefabs/Visitors";
    const string ScenePath = "Assets/Scenes/VisitorPreview.unity";

    // Fur variants are swapped on every "Fur" slot of a visitor.
    static readonly string[] FurMaterials = { "Fur_Gray", "Fur_Red", "Fur_GrayDyed", "Paint_Red" };

    // Markings (Omangi's face and cross, button X, lens X, tail stripes) live in this atlas.
    // Textured materials multiply it by their color; white cells keep the plain color.
    const string AtlasPath = "Assets/Models/Characters/Textures/VisitorAtlas.png";

    // fur > 0 uses the matte Fangame/VisitorFur shader with that clump strength; otherwise URP Lit.
    // Lit materials never use environment reflections and only glossy props keep specular highlights.
    static readonly (string name, Color color, float smoothness, bool textured, float fur)[] MaterialDefs =
    {
        ("Fur_Gray", new Color(0.42f, 0.42f, 0.44f), 0f, false, 0.6f),
        ("Fur_Red", new Color(0.62f, 0.12f, 0.12f), 0f, true, 0.6f),       // carries Omangi's face and cross
        ("Fur_GrayDyed", new Color(0.50f, 0.45f, 0.45f), 0f, true, 0.6f),  // Omangi dyed gray, a little reddish
        ("Paint_Red", new Color(0.75f, 0.08f, 0.06f), 0f, false, 0.1f),    // Koonmungchi in red paint, fur matted down
        ("NoseTip", new Color(0.08f, 0.08f, 0.09f), 0.35f, false, 0f),
        ("Button", Color.white, 0.35f, true, 0f),
        ("TailStripe", Color.white, 0f, true, 0.6f),
        ("Horn", new Color(0.06f, 0.05f, 0.05f), 0.2f, false, 0f),
        ("Ear", new Color(0.07f, 0.06f, 0.06f), 0f, false, 0.4f),
        ("PropBand", new Color(0.05f, 0.05f, 0.05f), 0.4f, false, 0f),
        ("PropHorn", new Color(0.10f, 0.02f, 0.02f), 0.5f, false, 0f),
        ("PropFelt", new Color(0.12f, 0.11f, 0.11f), 0f, false, 0f),
        ("PropPaper", new Color(0.55f, 0.55f, 0.52f), 0.05f, false, 0f),
        ("PropString", new Color(0.92f, 0.92f, 0.92f), 0.1f, false, 0f),
        ("PropStrap", new Color(0.35f, 0.20f, 0.10f), 0.2f, false, 0f),
        ("PropFrame", new Color(0.08f, 0.08f, 0.08f), 0.4f, false, 0f),
        ("PropLens", Color.white, 0.5f, true, 0f),
        ("FakeTailStripe", Color.white, 0f, true, 0.25f),                 // synthetic fur, flatter
    };

    [MenuItem("Tools/Visitors/Rebuild Prefabs")]
    public static void Build()
    {
        AssetDatabase.Refresh(); // pick up a freshly exported FBX/atlas
        EnsureFolder(MaterialDir);
        EnsureFolder(PrefabDir);
        CreateMaterials();
        ConfigureImporter();

        var model = AssetDatabase.LoadAssetAtPath<GameObject>(ModelPath);
        var koon = SavePrefab(model, "Koonmungchi", "Fur_Gray", "Body", "Koon_");
        var oma = SavePrefab(model, "Omangi", "Fur_Red", "Body", "Oma_");
        // Each visitor disguises as the other: its own fur change plus the other side's look-alike props.
        AddDisguise(koon, "Fur_Gray", "Paint_Red", "Fake_HornBand", "Fake_GoatEars");
        AddDisguise(oma, "Fur_Red", "Fur_GrayDyed", "Fake_ConeNose", "Fake_RaccoonTail", "Fake_XGlasses");
        // Only the real raccoon tail wags; the fake one stays stiff (a possible tell).
        AddTailWag(koon, "Koon_Tail");
        // Fixed full-costume variants, for the preview scene.
        var koonCostume = SavePrefab(koon, "Koonmungchi_OmaCostume", "Paint_Red",
            "Body", "Koon_", "Fake_HornBand", "Fake_GoatEars");
        var omaCostume = SavePrefab(oma, "Omangi_KoonCostume", "Fur_GrayDyed",
            "Body", "Oma_", "Fake_ConeNose", "Fake_RaccoonTail", "Fake_XGlasses");

        BuildPreviewScene(koon, oma, koonCostume, omaCostume);
        AssetDatabase.SaveAssets();
        Debug.Log("[Visitors] Rebuilt materials, prefabs and preview scene.");
    }

    static void CreateMaterials()
    {
        var atlasImporter = (TextureImporter)AssetImporter.GetAtPath(AtlasPath);
        atlasImporter.mipmapEnabled = false;
        atlasImporter.wrapMode = TextureWrapMode.Clamp;
        atlasImporter.SaveAndReimport();
        var atlas = AssetDatabase.LoadAssetAtPath<Texture2D>(AtlasPath);

        var lit = Shader.Find("Universal Render Pipeline/Lit");
        var furShader = Shader.Find("Fangame/VisitorFur");
        foreach (var (name, color, smoothness, textured, fur) in MaterialDefs)
        {
            var path = $"{MaterialDir}/{name}.mat";
            var mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null)
            {
                mat = new Material(lit);
                AssetDatabase.CreateAsset(mat, path);
            }
            mat.shader = fur > 0f ? furShader : lit;
            mat.SetColor("_BaseColor", color);
            mat.SetTexture("_BaseMap", textured ? atlas : null);
            if (fur > 0f)
            {
                mat.shaderKeywords = new string[0];
                mat.SetFloat("_FurScale", 9f);
                mat.SetFloat("_FurStrength", 1.5f * fur);
                mat.SetFloat("_Crease", 0.4f * fur);
                mat.SetFloat("_Fiber", 0.4f * fur);
                mat.SetFloat("_ColorVariation", 0.1f * fur);
                mat.SetFloat("_RimStrength", 0.8f * fur);
            }
            else
            {
                var highlights = smoothness >= 0.3f;
                mat.SetFloat("_Smoothness", smoothness);
                mat.SetFloat("_EnvironmentReflections", 0f);
                mat.EnableKeyword("_ENVIRONMENTREFLECTIONS_OFF");
                mat.SetFloat("_SpecularHighlights", highlights ? 1f : 0f);
                if (highlights)
                    mat.DisableKeyword("_SPECULARHIGHLIGHTS_OFF");
                else
                    mat.EnableKeyword("_SPECULARHIGHLIGHTS_OFF");
            }
            EditorUtility.SetDirty(mat);
        }
        AssetDatabase.SaveAssets();
    }

    static void ConfigureImporter()
    {
        var importer = (ModelImporter)AssetImporter.GetAtPath(ModelPath);
        importer.animationType = ModelImporterAnimationType.None;
        importer.importAnimation = false;
        importer.importCameras = false;
        importer.importLights = false;
        importer.importBlendShapes = false;
        importer.importNormals = ModelImporterNormals.Import; // custom normals smooth the low-poly body

        // FBX slot names match project material names, except "Fur" which defaults to gray.
        foreach (var remap in importer.GetExternalObjectMap().Keys.ToList())
            importer.RemoveRemap(remap);
        foreach (var (name, _, _, _, _) in MaterialDefs)
        {
            var slot = FurMaterials.Contains(name) ? (name == "Fur_Gray" ? "Fur" : null) : name;
            if (slot == null)
                continue;
            importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material), slot),
                AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{name}.mat"));
        }
        importer.SaveAndReimport();
    }

    static GameObject SavePrefab(GameObject source, string name, string fur, params string[] activePrefixes)
    {
        var go = (GameObject)PrefabUtility.InstantiatePrefab(source);
        go.name = name;
        foreach (Transform part in go.transform)
            part.gameObject.SetActive(activePrefixes.Any(p => part.name.StartsWith(p)));

        var furMat = AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{fur}.mat");
        foreach (var renderer in go.GetComponentsInChildren<Renderer>(true))
        {
            var mats = renderer.sharedMaterials;
            for (var i = 0; i < mats.Length; i++)
                if (mats[i] != null && FurMaterials.Contains(mats[i].name))
                    mats[i] = furMat;
            renderer.sharedMaterials = mats;
        }

        var prefab = PrefabUtility.SaveAsPrefabAsset(go, $"{PrefabDir}/{name}.prefab");
        Object.DestroyImmediate(go);
        return prefab;
    }

    static void AddDisguise(GameObject prefab, string naturalFur, string disguiseFur, params string[] propNames)
    {
        var path = AssetDatabase.GetAssetPath(prefab);
        var root = PrefabUtility.LoadPrefabContents(path);
        var disguise = root.GetComponent<VisitorDisguise>();
        if (disguise == null)
            disguise = root.AddComponent<VisitorDisguise>();

        var so = new SerializedObject(disguise);
        so.FindProperty("naturalFur").objectReferenceValue = AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{naturalFur}.mat");
        so.FindProperty("disguiseFur").objectReferenceValue = AssetDatabase.LoadAssetAtPath<Material>($"{MaterialDir}/{disguiseFur}.mat");
        var props = so.FindProperty("props");
        props.arraySize = propNames.Length;
        for (var i = 0; i < propNames.Length; i++)
            props.GetArrayElementAtIndex(i).objectReferenceValue = root.transform.Find(propNames[i]).gameObject;
        so.ApplyModifiedPropertiesWithoutUndo();

        PrefabUtility.SaveAsPrefabAsset(root, path);
        PrefabUtility.UnloadPrefabContents(root);
    }

    static void AddTailWag(GameObject prefab, string tailName)
    {
        var path = AssetDatabase.GetAssetPath(prefab);
        var root = PrefabUtility.LoadPrefabContents(path);
        var wag = root.GetComponent<TailWag>();
        if (wag == null)
            wag = root.AddComponent<TailWag>();

        var so = new SerializedObject(wag);
        so.FindProperty("tail").objectReferenceValue = root.transform.Find(tailName);
        so.ApplyModifiedPropertiesWithoutUndo();

        PrefabUtility.SaveAsPrefabAsset(root, path);
        PrefabUtility.UnloadPrefabContents(root);
    }

    static void BuildPreviewScene(params GameObject[] prefabs)
    {
        var scene = EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects, NewSceneMode.Single);

        // Visitors face +Z, so the camera looks back at them from the +Z side.
        var cam = Camera.main.transform;
        cam.SetPositionAndRotation(new Vector3(0f, 0.6f, 3f), Quaternion.Euler(5f, 180f, 0f));
        var sun = Object.FindFirstObjectByType<Light>();
        if (sun != null)
            sun.transform.rotation = Quaternion.Euler(40f, 160f, 0f);

        var ground = GameObject.CreatePrimitive(PrimitiveType.Plane);
        ground.name = "Ground";
        ground.transform.localScale = new Vector3(0.6f, 1f, 0.3f);

        for (var i = 0; i < prefabs.Length; i++)
        {
            var go = (GameObject)PrefabUtility.InstantiatePrefab(prefabs[i]);
            go.transform.position = new Vector3((i - 1.5f) * 1.1f, 0f, 0f);
        }
        EditorSceneManager.SaveScene(scene, ScenePath);
    }

    static void EnsureFolder(string path)
    {
        if (AssetDatabase.IsValidFolder(path))
            return;
        var parent = Path.GetDirectoryName(path).Replace('\\', '/');
        EnsureFolder(parent);
        AssetDatabase.CreateFolder(parent, Path.GetFileName(path));
    }
}
